<?php class Review{
public static function approved($activityId=null){if($activityId){$s=db()->prepare("SELECT rv.*,u.firstname,u.lastname FROM reviews rv JOIN users u ON u.id=rv.user_id WHERE rv.status='approved' AND rv.activity_id=? ORDER BY rv.id DESC");$s->execute([$activityId]);return $s->fetchAll();}return db()->query("SELECT rv.*,u.firstname,u.lastname,a.title FROM reviews rv JOIN users u ON u.id=rv.user_id JOIN activities a ON a.id=rv.activity_id WHERE rv.status='approved' ORDER BY rv.id DESC LIMIT 6")->fetchAll();}
public static function all(){return db()->query("SELECT rv.*,u.firstname,u.lastname,a.title FROM reviews rv JOIN users u ON u.id=rv.user_id JOIN activities a ON a.id=rv.activity_id ORDER BY rv.id DESC")->fetchAll();}
public static function create($uid,$d){$ok=db()->prepare("SELECT COUNT(*) FROM reservations r JOIN sessions s ON s.id=r.session_id WHERE r.user_id=? AND s.activity_id=? AND (r.status='completed' OR s.starts_at<NOW())");$ok->execute([$uid,(int)$d['activity_id']]);if(!$ok->fetchColumn())return false;$rating=max(1,min(5,(int)$d['rating']));$s=db()->prepare("INSERT INTO reviews(user_id,activity_id,rating,comment,status) VALUES(?,?,?,?,'pending')");$s->execute([$uid,(int)$d['activity_id'],$rating,trim($d['comment'])]);return true;}
public static function moderate($id,$status){if(!in_array($status,['approved','rejected'],true))return;$s=db()->prepare('UPDATE reviews SET status=? WHERE id=?');$s->execute([$status,$id]);}
}